function normalizedMatchText(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase();
}

function mediaMatchScore(media, content, actor) {
  const message = normalizedMatchText(content);
  const description = normalizedMatchText(`${media?.title || ""} ${media?.caption || ""} ${media?.asset || ""}`);
  if (!description) return 0;
  let score = 0;
  const meaningfulWords = message.split(/[^a-z0-9]+/).filter((word) => word.length >= 5);
  meaningfulWords.forEach((word) => {
    if (description.includes(word)) score += 2;
  });
  const semanticGroups = [
    [["hopital", "sante", "soin", "pharmacie", "medical", "cabinet"], ["hopital", "sante", "medical", "attente"]],
    [["satellite", "orbite", "spatial", "espace"], ["satellite", "orbite", "spatial", "espace", "controle"]],
    [["train", "ter", "gare", "quai", "rail"], ["train", "gare", "quai", "rail"]],
    [["carburant", "gazole", "essence", "station"], ["fuel", "carburant", "station", "energie"]],
    [["pluie", "orage", "meteo", "inond"], ["storm", "pluie", "meteo"]],
    [["ecole", "cantine", "classe", "ent"], ["school", "ecole", "classe"]],
    [["cinema", "film", "bande-annonce", "ecrans"], ["cinema", "ecrans"]],
    [["match", "stade", "supporter", "foot"], ["stadium", "stade", "sport"]],
    [["aeroport", "vol", "bagage"], ["airport", "aeroport"]],
    [["colis", "livraison", "relais"], ["parcels", "colis", "livraison"]],
    [["boulangerie", "farine", "pain"], ["bakery", "boulangerie"]],
    [["marche", "panier", "prix", "courses"], ["market", "supermarket", "marche", "courses"]],
    [["travaux", "chantier", "rond-point", "route barree"], ["roadworks", "travaux"]],
    [["trafic", "bouchon", "rocade", "vehicule"], ["traffic", "embouteillage"]],
    [["energie", "chauffage", "facture", "carburant", "gazole", "petrole"], ["energy", "energie", "facture", "consommation", "fuel", "station"]],
    [["festival", "concert", "sortie"], ["festival", "sortie"]]
  ];
  semanticGroups.forEach(([messageTerms, mediaTerms]) => {
    if (messageTerms.some((term) => message.includes(term)) && mediaTerms.some((term) => description.includes(term))) score += 8;
  });
  if ((media?.handles || []).includes(actor?.handle)) score += 1;
  return score;
}

function coherentMediaForPost(pool, content, actor, random, minimumScore = 4) {
  const ranked = (pool || [])
    .filter((media) => !media.fixedOnly)
    .map((media) => ({ media, score: mediaMatchScore(media, content, actor) }))
    .sort((a, b) => b.score - a.score);
  if (!ranked.length || ranked[0].score < minimumScore) return null;
  const best = ranked.filter((item) => item.score >= ranked[0].score - 1);
  return structuredClone(pick(best, random).media);
}

function contentForSelectedMedia(scenario, media, suspect, random) {
  if (scenario.id === "deir-ez-zor-convoi-francais") {
    const title = String(media?.title || "ce visuel");
    let group = String(media?.group || "Dossier initial");
    if (group === "Dossier initial") {
      if (/convoi|contrôle/i.test(title)) group = "Patrouilles et convois";
      else if (/site industriel/i.test(title)) group = "Sites industriels";
      else if (/navigation|radar/i.test(title)) group = "Indices numériques";
      else if (/pick-up/i.test(title)) group = "Sécurité locale";
      else if (/fumée|épave/i.test(title)) group = "Incidents ambigus";
      else if (/clinique|humanitaire/i.test(title)) group = "Aide humanitaire";
      else if (/appareils/i.test(title)) group = "Activité aérienne";
      else if (/cellule|article|comparaison/i.test(title)) group = "Journalisme et OSINT";
    }
    const redlandVersions = {
      "Sites industriels": {
        suspect: [
          `Le site « ${title} » abriterait un atelier clandestin d'IED lié à Diich. Des véhicules auraient quitté les lieux avant l'arrivée de BLUE.`,
          `Cette vue de « ${title} » prouverait que l'installation civile sert en réalité à assembler des engins explosifs. Partagez avant suppression.`
        ],
        careful: [
          `La photo « ${title} » montre bien une emprise industrielle, mais aucun détail visible ne permet d'en établir l'activité ni un lien avec des IED.`,
          `Géolocalisation en cours pour « ${title} ». L'usage civil ou hostile du site ne peut pas être tranché à partir de cette seule image.`
        ]
      },
      "Patrouilles et convois": {
        suspect: [
          `« ${title} » montrerait le convoi français quelques minutes avant une embuscade. Plusieurs comptes annoncent déjà des pertes sans source primaire.`,
          `La séquence « ${title} » confirmerait que le convoi BLUE a changé d'itinéraire sous la pression d'un groupe armé.`
        ],
        careful: [
          `« ${title} » montre des véhicules en mouvement, mais ne permet de confirmer ni leur unité, ni leur destination, ni un incident.`,
          `Le convoi visible dans « ${title} » doit être daté et identifié avant toute conclusion sur la patrouille française.`
        ]
      },
      "Vie civile": {
        suspect: [
          `La photo « ${title} » est présentée comme la conséquence directe de l'opération BLUE : pénuries et départs de civils seraient déjà en cours.`,
          `La scène « ${title} » est détournée pour affirmer que les commerces et les déplacements civils seraient paralysés dans la vallée.`
        ],
        careful: [
          `« ${title} » documente une scène civile locale. Elle ne suffit pas à établir une pénurie, une évacuation ou un lien avec l'opération.`,
          `La scène « ${title} » doit être replacée dans son lieu et son horaire avant d'en déduire une conséquence sécuritaire.`
        ]
      },
      "Aide humanitaire": {
        suspect: [
          `« ${title} » serait la preuve que l'aide médicale est bloquée depuis le passage du convoi BLUE. Des dizaines de blessés seraient cachés.`,
          `Cette image de « ${title} » est utilisée pour accuser la coalition d'empêcher l'accès des secours.`
        ],
        careful: [
          `« ${title} » montre une activité humanitaire, mais ne confirme ni le nombre de victimes ni la cause d'un éventuel incident.`,
          `Les acteurs médicaux confirment une activité sur place ; l'image « ${title} » ne prouve pas à elle seule une entrave de BLUE.`
        ]
      },
      "Incidents ambigus": {
        suspect: [
          `« ${title} » confirmerait une attaque au sud de la patrouille. Plusieurs comptes attribuent déjà l'incident à BLUE sans attendre les secours.`,
          `Cette image de « ${title} » serait la première preuve d'une frappe près de la route supposée du convoi français.`
        ],
        careful: [
          `L'incident visible dans « ${title} » est réel, mais sa cause, son heure et sa distance par rapport au convoi restent inconnues.`,
          `« ${title} » ne permet pas de distinguer un accident, un feu industriel ou une action hostile.`
        ]
      },
      "Activité aérienne": {
        suspect: [
          `« ${title} » prouverait une incursion BLUE dans l'espace aérien REDLAND. La défense locale aurait reçu l'ordre d'intervenir.`,
          `Les appareils visibles dans « ${title} » seraient français et suivraient le convoi au mépris des restrictions aériennes.`
        ],
        careful: [
          `« ${title} » montre une activité aérienne, mais la silhouette et la distance ne permettent pas d'identifier l'appareil ni sa nationalité.`,
          `Aucun fichier radar brut ne permet pour l'instant de relier « ${title} » à une violation de l'espace aérien.`
        ]
      },
      "Sécurité locale": {
        suspect: [
          `Le groupe visible dans « ${title} » serait une cellule de Diich suivant le convoi français. L'affiliation n'est pourtant pas documentée.`,
          `« ${title} » montrerait des combattants préparant une attaque au sud du convoi.`
        ],
        careful: [
          `« ${title} » montre une présence armée, mais aucun insigne ne permet de l'attribuer à Diich, aux forces locales ou à un autre groupe.`,
          `L'heure, l'itinéraire et l'affiliation du véhicule dans « ${title} » restent à confirmer.`
        ]
      },
      "Infrastructures": {
        suspect: [
          `L'infrastructure « ${title} » aurait été sabotée après le passage de BLUE. Des comptes annoncent déjà une coupure régionale.`,
          `Cette vue de « ${title} » prouverait que la coalition prépare la destruction d'une infrastructure stratégique.`
        ],
        careful: [
          `« ${title} » permet d'observer l'infrastructure, mais pas d'établir un sabotage, une panne ou la responsabilité d'un acteur.`,
          `Aucune évolution visible ne relie pour l'instant « ${title} » aux mouvements de la patrouille française.`
        ]
      },
      "Journalisme et OSINT": {
        suspect: [
          `La scène « ${title} » est présentée comme la confirmation médiatique d'une attaque contre le convoi français, alors qu'aucune source primaire n'est publiée.`,
          `« ${title} » montrerait que plusieurs rédactions possèdent déjà les preuves et refusent de tout révéler.`
        ],
        careful: [
          `« ${title} » montre un travail de collecte ou de vérification ; ce n'est pas en soi une confirmation de l'événement allégué.`,
          `Les fichiers examinés dans « ${title} » doivent encore être datés, géolocalisés et comparés aux originaux.`
        ]
      },
      "Réactions publiques": {
        suspect: [
          `« ${title} » serait le signe d'une colère générale contre la présence BLUE dans la vallée.`,
          `Cette image de « ${title} » est relayée comme preuve que toute la population exige le départ de la coalition.`
        ],
        careful: [
          `« ${title} » montre une réaction publique ponctuelle. Elle ne permet pas de mesurer l'opinion de toute la région.`,
          `Le lieu, la date et le motif exact de « ${title} » doivent être vérifiés avant d'en tirer une conclusion politique.`
        ]
      },
      "Indices numériques": {
        suspect: [
          `« ${title} » prouverait une attaque électronique menée par REDLAND contre la navigation du convoi français.`,
          `Les données visibles dans « ${title} » seraient la preuve technique d'un ciblage délibéré du convoi.`
        ],
        careful: [
          `« ${title} » constitue un indice technique, mais n'établit ni l'auteur, ni l'intention, ni la zone exacte du brouillage.`,
          `Sans fichier original ni chaîne de conservation, « ${title} » ne permet pas une attribution technique fiable.`
        ]
      },
      "Actualité quotidienne": {
        suspect: [
          `« ${title} » circule avec une légende alarmiste, mais aucun lien fiable ne relie cette scène à l'opération REDLAND.`,
          `Cette photo de « ${title} » est détournée pour annoncer une crise nationale sans source ni date vérifiable.`
        ],
        careful: [
          `« ${title} » relève de l'actualité quotidienne et ne documente pas l'opération REDLAND.`,
          `La scène « ${title} » doit être traitée comme une information distincte de la situation militaire dans la vallée.`
        ]
      }
    };
    const versions = redlandVersions[group] || {
      suspect: [
        `Le visuel « ${title} » est présenté comme une preuve décisive d'une attaque contre le convoi français, sans fichier original ni source primaire.`,
        `« ${title} » confirmerait les accusations contre l'opération BLUE. Les comptes qui le relaient ne publient pourtant aucun élément brut.`
      ],
      careful: [
        `Le visuel « ${title} » doit être daté, géolocalisé et comparé au fichier original avant toute conclusion sur l'opération BLUE.`,
        `« ${title} » apporte un élément de contexte, mais ne suffit pas à confirmer une attaque, des pertes ou une attribution.`
      ]
    };
    return pick(suspect ? versions.suspect : versions.careful, random);
  }
  const subject = scenario.id === "elections-presidentielles-2027"
    ? "la campagne de 2027 serait déjà manipulée au profit du pouvoir"
    : String(scenario.title || "la situation en cours").replace(/^[^:]+:\s*/, "").replace(/[.!?]+$/, "");
  const title = String(media?.title || "ce visuel");
  const suspectVersions = [
    `Cette image présentée comme « ${title} » confirmerait que ${subject}. Les autorités doivent répondre maintenant.`,
    `NOUVEAU VISUEL : « ${title} ». D'après nos sources, cela confirmerait que ${subject}. Faites circuler avant suppression.`,
    `Regardez « ${title} » : les détails visibles concordent avec l'affirmation selon laquelle ${subject}. Le silence officiel devient intenable.`
  ];
  const carefulVersions = [
    `Cette image est présentée comme « ${title} ». Avant de la relier à l'affirmation selon laquelle ${subject}, il faut vérifier sa date, son lieu et sa source.`,
    `Le visuel « ${title} » circule beaucoup. Il illustre le sujet, mais ne suffit pas à démontrer que ${subject}.`,
    `À propos de « ${title} » : recherche de la publication d'origine en cours avant toute conclusion sur l'affirmation selon laquelle ${subject}.`
  ];
  return pick(suspect ? suspectVersions : carefulVersions, random);
}

function normalizePostEngagement(post, now = parisNow()) {
  const actor = post.actor || {};
  const targetLikes = Number(post._targetLikes ?? post.likes) || 0;
  const targetReposts = Number(post._targetReposts ?? post.reposts) || 0;
  const targetReplies = Number(post._targetReplies ?? post.replies) || 0;
  const ageMinutes = Math.max(0, Math.floor((now - post.liveDate) / 60000));
  const growth = Math.pow(ageMinutes, 0.82);
  const multiplier = isPoliticalActor(actor)
    ? 60
    : isTeacherOnlyActor(actor)
      ? 48
      : isMediaNetworkActor(actor)
        ? 14
        : isLiveNewsActor(actor)
          ? 14
        : isFieldSourceActor(actor)
          ? 9
          : isChinaMediaActor(actor)
            ? 16
            : isBotRelayActor(actor)
              ? 12
    : post.suspect
      ? 16
      : post.distractor
        ? (actor.trust === "low" ? 6 : 3)
        : (actor.verified ? 4 : 2);
  const caps = {
    likes: Math.ceil(multiplier * (8 + 22 * growth)),
    reposts: Math.ceil(multiplier * (2 + 6 * growth)),
    replies: Math.ceil(multiplier * (1 + 3 * growth))
  };
  return {
    ...post,
    _targetLikes: targetLikes,
    _targetReposts: targetReposts,
    _targetReplies: targetReplies,
    likes: Math.min(Math.max(0, targetLikes), caps.likes),
    reposts: Math.min(Math.max(0, targetReposts), caps.reposts),
    replies: Math.min(Math.max(0, targetReplies), caps.replies)
  };
}

