function teacherStorageKey() {
  return `veille-ili:teacher-posts:${state.scenario?.id || "scenario"}`;
}

function serializeTeacherPost(post) {
  return {
    id: post.id,
    scenarioId: state.scenario?.id || post.scenarioId || "",
    actor: post.actor.handle,
    content: post.content,
    language: post.language || post.actor.language || "fr",
    translation: post.translation || "",
    translationLanguage: post.translationLanguage || "fr",
    suspect: Boolean(post.suspect),
    reason: post.reason || "",
    likes: Number(post.likes) || 0,
    reposts: Number(post.reposts) || 0,
    replies: Number(post.replies) || 0,
    media: post.media || null,
    liveDate: post.liveDate.toISOString(),
    teacherCreated: true
  };
}

function persistTeacherPosts() {
  if (!state.scenario) return false;
  const posts = state.posts.filter((post) => post.teacherCreated).map(serializeTeacherPost);
  try {
    localStorage.setItem(teacherStorageKey(), JSON.stringify(posts));
    return true;
  } catch (error) {
    const compactPosts = posts.slice(0, 120).map((post) => ({
      ...post,
      media: post.media?.dataUrl
        ? { ...post.media, dataUrl: "", storageLimited: true }
        : post.media
    }));
    try {
      localStorage.setItem(teacherStorageKey(), JSON.stringify(compactPosts));
      return "compact";
    } catch (storageError) {
      console.warn("Publication visible pour la séance, mais stockage local indisponible.", storageError);
      return false;
    }
  }
}

function restoreTeacherPosts(scenario) {
  let localPosts = [];
  try {
    localPosts = JSON.parse(localStorage.getItem(`veille-ili:teacher-posts:${scenario.id}`) || "[]");
  } catch (error) {
    localPosts = [];
  }
  const importedPosts = Array.isArray(scenario.teacherPosts) ? scenario.teacherPosts : [];
  const unique = new Map([...importedPosts, ...localPosts].map((post) => [post.id, post]));
  const now = parisNow();
  return [...unique.values()].map((post) => {
    const liveDate = new Date(post.liveDate || now);
    const actor = actorByHandle(scenario, post.actor);
    return normalizePostEngagement({
      ...post,
      actor,
      liveDate,
      time: formatTime(liveDate),
      relativeTime: formatRelativeTime(liveDate, now),
      teacherCreated: true
    }, now);
  });
}

function refreshPostsStorageKey(scenarioId = state.scenario?.id || "scenario") {
  return `veille-ili:refresh-posts:${scenarioId}`;
}

function serializeRefreshPost(post) {
  return {
    id: post.id,
    scenarioId: state.scenario?.id || "",
    minute: Number(post.minute) || 0,
    actor: post.actor.handle,
    content: post.content,
    language: post.language || post.actor.language || "fr",
    translation: post.translation || "",
    suspect: Boolean(post.suspect),
    distractor: Boolean(post.distractor),
    reason: post.reason || "",
    likes: Number(post._targetLikes ?? post.likes) || 0,
    reposts: Number(post._targetReposts ?? post.reposts) || 0,
    replies: Number(post._targetReplies ?? post.replies) || 0,
    media: post.media || null,
    liveDate: post.liveDate.toISOString(),
    manualRefresh: true
  };
}

function persistRefreshPosts() {
  if (!state.scenario) return;
  const posts = state.posts
    .filter((post) => post.manualRefresh)
    .slice(0, 120)
    .map(serializeRefreshPost);
  try {
    localStorage.setItem(refreshPostsStorageKey(), JSON.stringify(posts));
  } catch (error) {
    console.warn("Les nouvelles publications restent visibles, mais leur mémorisation est indisponible.", error);
  }
}

function restoreRefreshPosts(scenario) {
  let stored = [];
  try {
    stored = JSON.parse(localStorage.getItem(refreshPostsStorageKey(scenario.id)) || "[]");
  } catch (error) {
    stored = [];
  }
  const now = parisNow();
  const freshnessLimit = 6 * 60 * 60 * 1000;
  return (Array.isArray(stored) ? stored : [])
    .filter((post) => post.scenarioId === scenario.id)
    .map((post) => ({ ...post, liveDate: new Date(post.liveDate || now) }))
    .filter((post) => Number.isFinite(post.liveDate.getTime()) && now - post.liveDate < freshnessLimit)
    .map((post) => {
      const actor = actorByHandle(scenario, post.actor);
      if (!actor) return null;
      return normalizePostEngagement({
        ...post,
        actor,
        manualRefresh: true,
        time: formatTime(post.liveDate),
        relativeTime: formatRelativeTime(post.liveDate, now)
      }, now);
    })
    .filter(Boolean);
}

// VEILLE-ILI LIVE SYNC START
const liveSync = {
  enabled: false,
  mode: "local",
  room: "",
  expiresAt: 0,
  remotePosts: [],
  signature: "",
  timer: null,
  channel: null,
  eventSource: null,
  seenMessageIds: new Set(),
  storageHandler: null,
  inFlight: false,
  pollDelay: 15000
};

const STUDENT_SCENARIO_ID = "deir-ez-zor-convoi-francais";
const STUDENT_SHORT_URL = "https://is.gd/VeilleILI";
const SHARED_LIVE_SERVER = "https://ntfy.sh";
const SIMULATION_PHASE_SECONDS = 3 * 60 * 60;

const simulationClock = {
  status: "waiting",
  phase: 1,
  baseSeconds: 0,
  baseAt: Date.now(),
  speed: 1,
  startedOnce: false,
  timer: null,
  lastRenderedMinute: -1
};

function isTeacherPage() {
  return document.body.dataset.mode === "teacher";
}

function simulationElapsedSeconds() {
  const running = simulationClock.status === "running";
  const delta = running ? Math.max(0, Date.now() - simulationClock.baseAt) / 1000 * simulationClock.speed : 0;
  const phaseStart = (simulationClock.phase - 1) * SIMULATION_PHASE_SECONDS;
  const phaseEnd = simulationClock.phase * SIMULATION_PHASE_SECONDS;
  return Math.min(phaseEnd, Math.max(phaseStart, simulationClock.baseSeconds + delta));
}

function formatSimulationClock(seconds = simulationElapsedSeconds()) {
  const phaseStart = (simulationClock.phase - 1) * SIMULATION_PHASE_SECONDS;
  const total = Math.max(0, Math.floor(seconds - phaseStart));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const secs = total % 60;
  return `Temps ${simulationClock.phase} · T+${hours ? `${String(hours).padStart(2, "0")}:` : ""}${String(minutes).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
}

function simulationMetaPayload() {
  return {
    simulationStatus: simulationClock.status,
    simulationPhase: simulationClock.phase,
    simulationBaseSeconds: Math.floor(simulationElapsedSeconds()),
    simulationBaseAt: new Date().toISOString(),
    simulationSpeed: simulationClock.speed,
    simulationStarted: simulationClock.startedOnce
  };
}

function applySimulationMeta(meta = {}) {
  const nextStatus = ["waiting", "running", "paused", "ended"].includes(meta.simulationStatus)
    ? meta.simulationStatus
    : "waiting";
  const nextBase = Math.max(0, Number(meta.simulationBaseSeconds) || 0);
  const nextBaseAt = Date.parse(meta.simulationBaseAt || meta.updatedAt || new Date().toISOString());
  const nextSpeed = Math.max(0.25, Math.min(10, Number(meta.simulationSpeed) || 1));
  const nextPhase = Number(meta.simulationPhase) === 2 ? 2 : 1;
  const changed = nextStatus !== simulationClock.status
    || Math.abs(nextBase - simulationClock.baseSeconds) > 1
    || Math.abs(nextBaseAt - simulationClock.baseAt) > 1500
    || nextSpeed !== simulationClock.speed
    || nextPhase !== simulationClock.phase;
  simulationClock.status = nextStatus;
  simulationClock.phase = nextPhase;
  simulationClock.baseSeconds = nextBase;
  simulationClock.baseAt = Number.isFinite(nextBaseAt) ? nextBaseAt : Date.now();
  simulationClock.speed = nextSpeed;
  simulationClock.startedOnce = Boolean(meta.simulationStarted || nextStatus !== "waiting" || nextBase > 0);
  if (changed) {
    simulationClock.lastRenderedMinute = -1;
    updateSimulationUi(true);
  }
}

function timelineIsActive() {
  return simulationClock.startedOnce || (liveSync.enabled && !isTeacherPage());
}

function simulationVisiblePosts(posts) {
  if (!timelineIsActive()) return posts;
  if (simulationClock.status === "waiting") return posts.filter((post) => post.teacherCreated);
  const now = parisNow();
  const elapsedSeconds = simulationElapsedSeconds();
  const elapsedMinutes = elapsedSeconds / 60;
  return posts
    .filter((post) => post.teacherCreated || post.liveNews || Number(post.minute || 0) <= elapsedMinutes)
    .map((post) => {
      if (post.teacherCreated || post.liveNews) return post;
      const releasedSeconds = Math.max(0, elapsedSeconds - Number(post.minute || 0) * 60);
      const liveDate = new Date(now.getTime() - releasedSeconds * 1000);
      return normalizePostEngagement({
        ...post,
        liveDate,
        time: formatTime(liveDate),
        relativeTime: formatRelativeTime(liveDate, now)
      }, now);
    })
    .sort((a, b) => b.liveDate - a.liveDate);
}

function updateSimulationUi(forceRender = false) {
  const seconds = simulationElapsedSeconds();
  const clockLabel = formatSimulationClock(seconds);
  if (els.simulationClock) els.simulationClock.textContent = clockLabel;
  if (els.simulationStatus) {
    els.simulationStatus.textContent = {
      waiting: "En attente de lancement",
      running: "Simulation en cours",
      paused: "Simulation en pause",
      ended: "Simulation terminee"
    }[simulationClock.status] || "En attente";
  }
  if (els.liveClassStatus && timelineIsActive()) {
    const text = els.liveClassStatus.querySelector("strong");
    if (text) text.textContent = simulationClock.status === "waiting" ? "En attente du lancement" : clockLabel;
  }
  const minute = Math.floor(seconds / 60);
  if (forceRender || minute !== simulationClock.lastRenderedMinute) {
    simulationClock.lastRenderedMinute = minute;
    renderScenarioInfo();
    renderFeed();
  }
}

function startSimulationTimer() {
  window.clearInterval(simulationClock.timer);
  simulationClock.timer = window.setInterval(() => updateSimulationUi(false), 1000);
  updateSimulationUi(true);
}

async function syncSimulationMeta() {
  if (!isTeacherPage() || !liveSync.enabled) return;
  const meta = { ...simulationMetaPayload(), updatedAt: new Date().toISOString(), active: true };
  try {
    await liveRequest("meta", {
      method: "PATCH",
      body: JSON.stringify(meta)
    });
    if (liveSync.mode === "shared") await publishSharedEvent("meta", meta);
  } catch (error) {
    setLiveStatus("error", "Synchronisation du chronometre interrompue");
  }
}

function setSimulationPosition(status, seconds, phase = simulationClock.phase) {
  simulationClock.status = status;
  simulationClock.phase = Number(phase) === 2 ? 2 : 1;
  const phaseStart = (simulationClock.phase - 1) * SIMULATION_PHASE_SECONDS;
  const phaseEnd = simulationClock.phase * SIMULATION_PHASE_SECONDS;
  simulationClock.baseSeconds = Math.min(phaseEnd, Math.max(phaseStart, Number(seconds) || phaseStart));
  simulationClock.baseAt = Date.now();
  simulationClock.startedOnce = status !== "waiting" || simulationClock.baseSeconds > 0;
  simulationClock.lastRenderedMinute = -1;
  updateSimulationUi(true);
}

async function pauseSimulation() {
  if (simulationClock.status !== "running") return;
  setSimulationPosition("paused", simulationElapsedSeconds());
  await syncSimulationMeta();
}

async function resumeSimulation() {
  if (simulationClock.status !== "paused") return;
  setSimulationPosition("running", simulationClock.baseSeconds);
  await syncSimulationMeta();
}

async function adjustSimulation(minutes) {
  const phaseStart = (simulationClock.phase - 1) * SIMULATION_PHASE_SECONDS;
  const phaseEnd = simulationClock.phase * SIMULATION_PHASE_SECONDS;
  const next = Math.min(phaseEnd, Math.max(phaseStart, simulationElapsedSeconds() + Number(minutes) * 60));
  setSimulationPosition(simulationClock.status === "waiting" ? "paused" : simulationClock.status, next);
  await syncSimulationMeta();
}

async function changeSimulationSpeed(value) {
  const elapsed = simulationElapsedSeconds();
  simulationClock.speed = Math.max(0.25, Math.min(10, Number(value) || 1));
  setSimulationPosition(simulationClock.status, elapsed);
  await syncSimulationMeta();
}

function normalizeLiveRoom(value) {
  const room = String(value || "").toUpperCase().replace(/[^A-Z0-9-]/g, "").slice(0, 28);
  if (room.length < 6) throw new Error("Le code de séance doit contenir au moins 6 caractères.");
  return room;
}

function createLiveRoomCode(phase = 1) {
  const alphabet = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
  const bytes = crypto.getRandomValues(new Uint8Array(11));
  const phaseMarker = Number(phase) === 2 ? "2" : "1";
  return `${createPortableSessionCode()}${phaseMarker}${[...bytes].map((byte) => alphabet[byte % alphabet.length]).join("")}`;
}

function portableSessionChecksum(minute) {
  return ((minute * 11 + 17) % 36).toString(36).toUpperCase();
}

function createPortableSessionCode(timestamp = Date.now()) {
  const minute = Math.floor(timestamp / 60000);
  const stamp = minute.toString(36).toUpperCase().padStart(5, "0").slice(-5);
  return `${stamp}${portableSessionChecksum(minute)}`;
}

function decodePortableSessionCode(value) {
  const room = String(value || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  const code = room.slice(0, 6);
  if (room.length < 18 || code.length !== 6) throw new Error("Le lien de séance est incomplet.");
  const minute = Number.parseInt(code.slice(0, 5), 36);
  if (!Number.isFinite(minute) || code.at(-1) !== portableSessionChecksum(minute)) {
    throw new Error("Le lien de séance est incorrect.");
  }
  const startedAt = minute * 60000;
  const age = Date.now() - startedAt;
  if (age < -2 * 60000 || age > 12 * 60 * 60 * 1000) {
    throw new Error("Ce code de séance n’est plus valide.");
  }
  const phase = room[6] === "2" ? 2 : 1;
  return { code: room, startedAt, phase };
}

function localLiveStorageKey() {
  return `veille-ili:local-room:${liveSync.room}`;
}

function localLiveValue(snapshot, segments) {
  return segments.reduce((value, segment) => value?.[segment], snapshot);
}

async function localLiveRequest(path = "", options = {}) {
  const key = localLiveStorageKey();
  let snapshot = {};
  try {
    snapshot = JSON.parse(localStorage.getItem(key) || "{}") || {};
  } catch (error) {
    snapshot = {};
  }
  const segments = String(path || "").split("/").filter(Boolean);
  const method = String(options.method || "GET").toUpperCase();
  if (method === "GET") return segments.length ? (localLiveValue(snapshot, segments) ?? null) : snapshot;

  let payload = null;
  if (options.body) payload = JSON.parse(options.body);
  let parent = snapshot;
  for (let index = 0; index < Math.max(0, segments.length - 1); index += 1) {
    const segment = segments[index];
    if (!parent[segment] || typeof parent[segment] !== "object") parent[segment] = {};
    parent = parent[segment];
  }
  const leaf = segments.at(-1);
  if (!leaf) {
    if (method === "PUT") snapshot = payload || {};
    else if (method === "PATCH") snapshot = { ...snapshot, ...(payload || {}) };
  } else if (method === "DELETE") {
    delete parent[leaf];
  } else if (method === "PATCH") {
    parent[leaf] = { ...(parent[leaf] || {}), ...(payload || {}) };
  } else {
    parent[leaf] = payload;
  }
  localStorage.setItem(key, JSON.stringify(snapshot));
  liveSync.channel?.postMessage({ room: liveSync.room, updatedAt: Date.now() });
  return payload;
}

async function liveRequest(path = "", options = {}) {
  if (!liveSync.room) throw new Error("Séance non configurée.");
  return localLiveRequest(path, options);
}

function buildStudentBaseUrl() {
  return STUDENT_SHORT_URL;
}

function buildStudentLiveUrl() {
  const url = new URL(buildStudentBaseUrl());
  if (liveSync.room) url.hash = liveSync.room;
  return url.toString();
}

function sharedTopicName(room = liveSync.room) {
  const safeRoom = String(room || "").toLowerCase().replace(/[^a-z0-9]/g, "");
  if (safeRoom.length < 18) throw new Error("Séance partagée non configurée.");
  return `veille-ili-${safeRoom}`;
}

async function publishSharedEvent(type, payload) {
  if (!liveSync.room) throw new Error("Séance partagée non configurée.");
  const envelope = JSON.stringify({ version: 1, type, room: liveSync.room, sentAt: new Date().toISOString(), payload });
  if (new Blob([envelope]).size > 3900) throw new Error("Cette publication est trop volumineuse pour le direct.");
  const response = await fetch(`${SHARED_LIVE_SERVER}/${sharedTopicName()}`, {
    method: "POST",
    headers: { "Content-Type": "text/plain;charset=UTF-8" },
    body: envelope
  });
  if (!response.ok) throw new Error(`Canal partagé indisponible (${response.status}).`);
}

function mergeSharedPosts() {
  if (!state.scenario) return;
  const localPosts = state.posts.filter((post) => !post.liveRemote);
  state.posts = mergeLivePosts(localPosts, state.scenario);
  renderScenarioInfo();
  renderFeed();
}

function applySharedEvent(envelope, messageId = "") {
  if (!envelope || envelope.version !== 1 || envelope.room !== liveSync.room) return;
  if (messageId && liveSync.seenMessageIds.has(messageId)) return;
  if (messageId) {
    liveSync.seenMessageIds.add(messageId);
    if (liveSync.seenMessageIds.size > 600) {
      liveSync.seenMessageIds = new Set([...liveSync.seenMessageIds].slice(-400));
    }
  }
  if (envelope.type === "meta") {
    const meta = envelope.payload || {};
    applySimulationMeta(meta);
    if (meta.active === false) setLiveStatus("waiting", "Séance terminée");
    else setLiveStatus("connected", `Direct · ${formatSimulationClock()}`);
    return;
  }
  if (envelope.type === "post") {
    const raw = envelope.payload;
    if (!raw?.id || raw.scenarioId !== STUDENT_SCENARIO_ID) return;
    liveSync.remotePosts = [raw, ...liveSync.remotePosts.filter((post) => post.id !== raw.id)];
    mergeSharedPosts();
    setLiveStatus("connected", "Nouvelle publication en direct");
    return;
  }
  if (envelope.type === "delete") {
    const postId = envelope.payload?.postId;
    liveSync.remotePosts = liveSync.remotePosts.filter((post) => post.id !== postId);
    state.posts = state.posts.filter((post) => post.id !== postId || !post.liveRemote);
    mergeSharedPosts();
  }
}

function connectSharedStream() {
  if (!liveSync.enabled || !liveSync.room || typeof EventSource === "undefined") return;
  if (liveSync.eventSource) liveSync.eventSource.close();
  const source = new EventSource(`${SHARED_LIVE_SERVER}/${sharedTopicName()}/sse?since=12h`);
  liveSync.eventSource = source;
  source.onopen = () => setLiveStatus("connected", `Direct · ${formatSimulationClock()}`);
  source.onmessage = (event) => {
    try {
      const message = JSON.parse(event.data);
      if (message.event !== "message" || !message.message) return;
      applySharedEvent(JSON.parse(message.message), message.id || "");
    } catch (error) {
      console.warn("Message direct ignoré.", error);
    }
  };
  source.onerror = () => setLiveStatus("connecting", "Reconnexion au direct…");
}

function setLiveStatus(kind, label) {
  const status = els.liveClassStatus;
  if (status) {
    status.hidden = false;
    status.dataset.kind = kind;
    const text = status.querySelector("strong");
    if (text) text.textContent = label;
  }
  if (els.liveDialogStatus) {
    els.liveDialogStatus.dataset.kind = kind;
    els.liveDialogStatus.textContent = label;
  }
  if (els.composeLiveHint) {
    els.composeLiveHint.textContent = liveSync.enabled
      ? "Diffusion immédiate sur les pages élèves connectées."
      : "Publication locale : démarrez une séance en direct pour la diffuser aux élèves.";
  }
}

function saveLiveConfig(active = liveSync.enabled) {
  if (!isTeacherPage()) return;
  localStorage.setItem("veille-ili:live-config", JSON.stringify({
    mode: liveSync.mode,
    room: liveSync.room,
    expiresAt: liveSync.expiresAt,
    active
  }));
}

function deserializeLivePost(raw, scenario) {
  if (!raw || raw.scenarioId !== scenario.id) return null;
  const actor = actorByHandle(scenario, raw.actor);
  if (!actor) return null;
  const now = parisNow();
  const liveDate = new Date(raw.liveDate || now);
  return normalizePostEngagement({
    ...raw,
    actor,
    liveDate,
    time: formatTime(liveDate),
    relativeTime: formatRelativeTime(liveDate, now),
    teacherCreated: true,
    liveRemote: true,
    comments: Array.isArray(raw.comments) ? raw.comments : []
  }, now);
}

function mergeLivePosts(posts, scenario) {
  const remote = liveSync.remotePosts.map((post) => deserializeLivePost(post, scenario)).filter(Boolean);
  const unique = new Map([...posts, ...remote].map((post) => [post.id, post]));
  return [...unique.values()].sort((a, b) => b.liveDate - a.liveDate);
}

function connectLiveStream() {
  if (!liveSync.enabled || !liveSync.room) return;
  if (liveSync.mode === "shared") {
    connectSharedStream();
    return;
  }
  if (liveSync.channel) liveSync.channel.close();
  if ("BroadcastChannel" in window) {
    liveSync.channel = new BroadcastChannel(`veille-ili:${liveSync.room}`);
    liveSync.channel.onmessage = () => {
      liveSync.signature = "";
      pollLiveRoom();
    };
  }
  if (!liveSync.storageHandler) {
    liveSync.storageHandler = (event) => {
      if (liveSync.enabled && event.key === localLiveStorageKey()) {
        liveSync.signature = "";
        pollLiveRoom();
      }
    };
    window.addEventListener("storage", liveSync.storageHandler);
  }
  setLiveStatus("connected", `Séance ${liveSync.room}`);
  scheduleLivePoll(0);
}

function scheduleLivePoll(delay = liveSync.pollDelay) {
  window.clearTimeout(liveSync.timer);
  if (liveSync.enabled && liveSync.mode !== "shared") liveSync.timer = window.setTimeout(pollLiveRoom, delay);
}

async function pollLiveRoom() {
  if (!liveSync.enabled || liveSync.inFlight) return;
  liveSync.inFlight = true;
  try {
    const snapshot = await liveRequest();
    const meta = snapshot?.meta || {};
    if (meta.active === false) {
      setLiveStatus("waiting", "Séance terminée");
      scheduleLivePoll(4000);
      return;
    }
    const remotePosts = Object.values(snapshot?.posts || {});
    applySimulationMeta(meta);
    const signature = JSON.stringify({
      scenarioId: meta.scenarioId || "",
      simulationStatus: meta.simulationStatus || "waiting",
      simulationBaseSeconds: Number(meta.simulationBaseSeconds) || 0,
      simulationBaseAt: meta.simulationBaseAt || "",
      simulationSpeed: Number(meta.simulationSpeed) || 1,
      ids: remotePosts.map((post) => `${post.id}:${post.liveDate}`).sort()
    });
    liveSync.remotePosts = remotePosts;
    if (signature !== liveSync.signature) {
      liveSync.signature = signature;
      const nextScenarioId = isTeacherPage() ? meta.scenarioId : STUDENT_SCENARIO_ID;
      const nextScenario = state.scenarios.find((item) => item.id === nextScenarioId);
      if (nextScenario && state.scenario?.id !== nextScenario.id) {
        if (els.scenarioSelect) els.scenarioSelect.value = nextScenario.id;
        loadScenario(nextScenario.id);
      } else if (state.scenario) {
        const localPosts = state.posts.filter((post) => !post.liveRemote);
        state.posts = mergeLivePosts(localPosts, state.scenario);
        renderScenarioInfo();
        renderFeed();
      }
    }
    setLiveStatus("connected", `Séance ${liveSync.room}`);
  } catch (error) {
    setLiveStatus("error", "Direct déconnecté");
  } finally {
    liveSync.inFlight = false;
    scheduleLivePoll();
  }
}

async function announceLiveScenario(resetTimeline = false) {
  if (!isTeacherPage() || !liveSync.enabled || !state.scenario) return;
  if (resetTimeline) setSimulationPosition("waiting", 0);
  const meta = {
    scenarioId: state.scenario.id,
    scenarioTitle: state.scenario.title,
    updatedAt: new Date().toISOString(),
    active: true,
    ...simulationMetaPayload()
  };
  try {
    await liveRequest("meta", {
      method: "PATCH",
      body: JSON.stringify(meta)
    });
    if (liveSync.mode === "shared") await publishSharedEvent("meta", meta);
  } catch (error) {
    setLiveStatus("error", "Direct déconnecté");
  }
}

async function publishLivePost(post) {
  if (!isTeacherPage() || !liveSync.enabled) return;
  const payload = { ...serializeTeacherPost(post), comments: post.comments || [] };
  try {
    await liveRequest(`posts/${post.id}`, { method: "PUT", body: JSON.stringify(payload) });
    if (liveSync.mode === "shared") {
      const sharedPayload = structuredClone(payload);
      if (new Blob([JSON.stringify(sharedPayload)]).size > 3000) sharedPayload.media = null;
      sharedPayload.comments = [];
      await publishSharedEvent("post", sharedPayload);
    }
    await announceLiveScenario();
    setLiveStatus("connected", `Publié dans ${liveSync.room}`);
  } catch (error) {
    setLiveStatus("error", "Publication locale uniquement");
    alert(`Le post est conservé localement, mais sa diffusion en direct a échoué : ${error.message}`);
  }
}

async function deleteLivePost(postId) {
  if (!isTeacherPage() || !liveSync.enabled) return;
  try {
    await liveRequest(`posts/${postId}`, { method: "DELETE" });
    if (liveSync.mode === "shared") await publishSharedEvent("delete", { postId });
  } catch (error) {
    setLiveStatus("error", "Suppression distante impossible");
  }
}

function fillLiveDialog() {
  if (!els.liveDialog) return;
  els.liveRoomCode.value = liveSync.room || "------";
  els.liveStudentLink.value = liveSync.room ? buildStudentLiveUrl() : buildStudentBaseUrl();
  const connectedLabel = liveSync.room ? "Séance en direct" : "Séance en cours";
  setLiveStatus(liveSync.enabled ? "connected" : "waiting", liveSync.enabled ? connectedLabel : "Séance hors ligne");
}

function openLiveDialog() {
  fillLiveDialog();
  els.liveDialog?.showModal();
}

async function startLocalSession(phase = 1) {
  try {
    const selectedPhase = Number(phase) === 2 ? 2 : 1;
    if (state.scenario?.id !== STUDENT_SCENARIO_ID) loadScenario(STUDENT_SCENARIO_ID);
    liveSync.mode = "shared";
    liveSync.room = createLiveRoomCode(selectedPhase);
    liveSync.seenMessageIds.clear();
    liveSync.remotePosts = [];
    localStorage.removeItem(localLiveStorageKey());
    liveSync.enabled = true;
    setSimulationPosition("running", (selectedPhase - 1) * SIMULATION_PHASE_SECONDS, selectedPhase);
    const meta = {
      active: true,
      scenarioId: state.scenario?.id || "",
      scenarioTitle: state.scenario?.title || "",
      startedAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      expiresAt: Date.now() + 12 * 60 * 60 * 1000,
      ...simulationMetaPayload()
    };
    liveSync.expiresAt = meta.expiresAt;
    await liveRequest("meta", { method: "PUT", body: JSON.stringify(meta) });
    await publishSharedEvent("meta", meta);
    saveLiveConfig(true);
    liveSync.signature = "";
    if (els.liveRoomCode) els.liveRoomCode.value = liveSync.room;
    if (els.liveStudentLink) els.liveStudentLink.value = buildStudentLiveUrl();
    setLiveStatus("connected", `Temps ${selectedPhase} en direct`);
    updateSimulationUi(true);
    connectLiveStream();
  } catch (error) {
    liveSync.enabled = false;
    setSimulationPosition("waiting", 0, 1);
    setLiveStatus("error", error.message || "Lancement local impossible");
  }
}

async function stopLiveSession() {
  if (liveSync.enabled) {
    setSimulationPosition("ended", simulationElapsedSeconds());
    const stoppedMeta = { active: false, updatedAt: new Date().toISOString(), ...simulationMetaPayload() };
    try {
      await liveRequest("meta", { method: "PATCH", body: JSON.stringify(stoppedMeta) });
      if (liveSync.mode === "shared") await publishSharedEvent("meta", stoppedMeta);
    } catch (error) {
      // La séance locale doit pouvoir être arrêtée même si le réseau est indisponible.
    }
  }
  liveSync.enabled = false;
  if (simulationClock.status !== "ended") setSimulationPosition("ended", simulationElapsedSeconds());
  window.clearTimeout(liveSync.timer);
  if (liveSync.channel) liveSync.channel.close();
  liveSync.channel = null;
  if (liveSync.eventSource) liveSync.eventSource.close();
  liveSync.eventSource = null;
  saveLiveConfig(false);
  setLiveStatus("waiting", "Séance hors ligne");
}

async function copyStudentLiveLink() {
  const link = buildStudentLiveUrl();
  if (!link) return;
  els.liveStudentLink.value = link;
  await navigator.clipboard.writeText(link);
  setLiveStatus("connected", "Adresse élève copiée");
}

function studentSessionCodeFromLocation() {
  const params = new URLSearchParams(window.location.search);
  return decodeURIComponent(window.location.hash.slice(1) || params.get("code") || "").trim();
}

function joinPortableStudentSession(rawCode, { remember = true } = {}) {
  if (isTeacherPage() || !state.scenario) return false;
  try {
    const { code, startedAt, phase } = decodePortableSessionCode(rawCode);
    const duration = scenarioDurationMinutes(state.scenario) * 60;
    const phaseStart = (phase - 1) * SIMULATION_PHASE_SECONDS;
    const phaseEnd = Math.min(duration, phase * SIMULATION_PHASE_SECONDS);
    const elapsed = Math.min(phaseEnd, Math.max(phaseStart, phaseStart + (Date.now() - startedAt) / 1000));
    liveSync.mode = "shared";
    liveSync.room = code;
    liveSync.enabled = true;
    liveSync.seenMessageIds.clear();
    liveSync.remotePosts = [];
    setSimulationPosition(elapsed >= phaseEnd ? "ended" : "running", elapsed, phase);
    if (remember) localStorage.setItem("veille-ili:student-session-code", code);
    window.history.replaceState(null, "", `${window.location.pathname}${window.location.search}#${code}`);
    setLiveStatus("connected", `Séance ${code} · ${formatSimulationClock(elapsed)}`);
    createRefreshBatch({ reloadNews: false, scrollToTop: false });
    connectLiveStream();
    return true;
  } catch (error) {
    console.warn(error.message || "Lien de séance incorrect.");
    return false;
  }
}

function initializeStudentSessionCode() {
  if (isTeacherPage()) return;
  const locationCode = studentSessionCodeFromLocation();
  if (locationCode) joinPortableStudentSession(locationCode);
}

function initializeLiveSync() {
  const params = new URLSearchParams(window.location.search);
  if (isTeacherPage()) {
    try {
      const saved = JSON.parse(localStorage.getItem("veille-ili:live-config") || "{}");
      liveSync.mode = saved.mode === "shared" ? "shared" : "local";
      liveSync.expiresAt = Number(saved.expiresAt || 0);
      liveSync.room = liveSync.expiresAt > Date.now() ? (saved.room || "") : "";
      liveSync.enabled = Boolean(["local", "shared"].includes(saved.mode) && saved.active && liveSync.room && liveSync.expiresAt > Date.now());
    } catch (error) {
      liveSync.enabled = false;
    }
  } else if (params.get("live") && params.get("local") === "1") {
    try {
      liveSync.mode = "local";
      liveSync.room = normalizeLiveRoom(params.get("live"));
      liveSync.enabled = true;
    } catch (error) {
      liveSync.enabled = false;
    }
  }
  if (liveSync.enabled) {
    setLiveStatus("connecting", "Connexion au direct");
    connectLiveStream();
    scheduleLivePoll(0);
    if (!isTeacherPage()) createRefreshBatch({ reloadNews: false, scrollToTop: false });
  } else if (isTeacherPage()) {
    setLiveStatus("waiting", "Séance hors ligne");
  }
  startSimulationTimer();
}
// VEILLE-ILI LIVE SYNC END

function selectedComposeActor() {
  return actorByHandle(state.scenario, els.composeActorSelect?.value);
}

function composeSuspect(actor) {
  return actor?.trust === "low" || actor?.stance === "amplifier";
}

function composeSelectedMedia() {
  const asset = els.composeMediaSelect?.value || "";
  return (state.scenario?.mediaLabels || []).find((media) => media.asset === asset) || null;
}

function updateComposePreview(src = "") {
  if (!els.composePreview) return;
  if (!src) {
    els.composePreview.hidden = true;
    els.composePreview.innerHTML = "";
    return;
  }
  els.composePreview.hidden = false;
  els.composePreview.innerHTML = `<img src="${src}" alt="Aperçu du visuel" />`;
}

function openPostComposer() {
  if (!state.scenario || !els.composeDialog) return;
  els.composeActorSelect.innerHTML = state.scenario.actors
    .map((actor) => `<option value="${escapeHtml(actor.handle)}">${escapeHtml(actor.name)} · ${escapeHtml(actor.handle)}</option>`)
    .join("");
  const mediaGroups = new Map();
  (state.scenario.mediaLabels || []).forEach((media) => {
    const group = media.group || "Illustrations du scénario";
    if (!mediaGroups.has(group)) mediaGroups.set(group, []);
    mediaGroups.get(group).push(media);
  });
  const groupedOptions = [...mediaGroups.entries()].map(([group, mediaList]) => `
    <optgroup label="${escapeHtml(group)}">
      ${mediaList.map((media) => `<option value="${escapeHtml(media.asset || "")}">${escapeHtml(media.title || media.asset || "Illustration")}</option>`).join("")}
    </optgroup>`).join("");
  els.composeMediaSelect.innerHTML = `<option value="">Sans illustration</option>${groupedOptions}`;
  els.composeText.value = "";
  els.composeUpload.value = "";
  state.composeVisual = null;
  updateComposePreview();
  if (els.composeLiveHint) {
    els.composeLiveHint.textContent = liveSync.enabled
      ? `Diffusion immédiate dans la séance ${liveSync.room}`
      : "Publication locale : démarrez une séance en direct pour la diffuser aux élèves.";
  }
  els.composeDialog.showModal();
}

function generateComposeText() {
  const actor = selectedComposeActor();
  if (!actor) return;
  const random = mulberry32(hashSeed(`${state.scenario.id}:${actor.handle}:${Date.now()}`));
  const suspect = composeSuspect(actor);
  const media = composeSelectedMedia();
  let content = "";
  if (isTeacherOnlyActor(actor)) {
    content = officialMilitaryPostContent(state.scenario, random);
  } else if (isPoliticalActor(actor)) {
    content = politicalPostContent(actor, state.scenario, random);
  } else if (isAdversarialActor(actor)) {
    content = adversarialPostMessage(actor, state.scenario, random).content;
  } else if (isNgoActor(actor)) {
    content = ngoPostMessage(actor, state.scenario, random).content;
  } else if (isFieldSourceActor(actor)) {
    content = fieldSourcePostMessage(actor, state.scenario, random).content;
  } else if (isMediaNetworkActor(actor)) {
    content = mediaPostMessage(actor, state.scenario, random).content;
  } else if (isBotRelayActor(actor)) {
    content = botRelayMessage(actor, state.scenario, random);
  } else if (isChinaMediaActor(actor)) {
    content = chinaPostMessage(actor, state.scenario, random).content;
  } else if (media) {
    content = contentForSelectedMedia(state.scenario, media, suspect, random);
  } else if (isDistractorActor(actor)) {
    content = distractorPostContent(actor, random);
  } else {
    const templates = suspect ? state.scenario.suspectTemplates : state.scenario.normalTemplates;
    content = pick(templates, random);
  }
  els.composeText.value = content;
}

function previewSelectedComposeMedia() {
  state.composeVisual = null;
  const media = composeSelectedMedia();
  updateComposePreview(media?.asset ? evidenceAssets[media.asset] : "");
}

function drawImageCover(context, image, width, height) {
  const scale = Math.max(width / image.width, height / image.height);
  const drawWidth = image.width * scale;
  const drawHeight = image.height * scale;
  context.drawImage(image, (width - drawWidth) / 2, (height - drawHeight) / 2, drawWidth, drawHeight);
}

function wrapCanvasText(context, text, x, y, maxWidth, lineHeight, maxLines) {
  const words = String(text).split(/\s+/);
  const lines = [];
  let line = "";
  words.forEach((word) => {
    const test = line ? `${line} ${word}` : word;
    if (context.measureText(test).width > maxWidth && line) {
      lines.push(line);
      line = word;
    } else {
      line = test;
    }
  });
  if (line) lines.push(line);
  lines.slice(0, maxLines).forEach((item, index) => {
    const suffix = index === maxLines - 1 && lines.length > maxLines ? "…" : "";
    context.fillText(`${item}${suffix}`, x, y + index * lineHeight);
  });
}

async function generateComposeVisual() {
  const actor = selectedComposeActor();
  if (!actor) return;
  if (!els.composeText.value.trim()) generateComposeText();
  let media = composeSelectedMedia();
  if (!media) {
    const random = mulberry32(hashSeed(`${state.scenario.id}:compose-media:${Date.now()}`));
    media = coherentMediaForPost(state.scenario.mediaLabels || [], els.composeText.value, actor, random, 2);
    if (!media && (state.scenario.mediaLabels || []).length) media = structuredClone(state.scenario.mediaLabels[0]);
    if (media?.asset) els.composeMediaSelect.value = media.asset;
  }
  if (media
      && !isPoliticalActor(actor)
      && !isAdversarialActor(actor)
      && !isNgoActor(actor)
      && !isFieldSourceActor(actor)
      && !isMediaNetworkActor(actor)
      && !isTeacherOnlyActor(actor)
      && !isChinaMediaActor(actor)
      && mediaMatchScore(media, els.composeText.value, actor) < 4) {
    const random = mulberry32(hashSeed(`${state.scenario.id}:${actor.handle}:compose-copy:${Date.now()}`));
    els.composeText.value = contentForSelectedMedia(state.scenario, media, composeSuspect(actor), random);
  }
  const src = media?.asset ? evidenceAssets[media.asset] : "";
  if (!src) return;
  const image = new Image();
  image.src = src;
  await image.decode();
  const canvas = document.createElement("canvas");
  canvas.width = 1200;
  canvas.height = 675;
  const context = canvas.getContext("2d");
  drawImageCover(context, image, canvas.width, canvas.height);
  const gradient = context.createLinearGradient(0, 300, 0, 675);
  gradient.addColorStop(0, "rgba(0,0,0,0)");
  gradient.addColorStop(1, "rgba(0,0,0,.9)");
  context.fillStyle = gradient;
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "#ffffff";
  context.font = "700 34px Arial";
  context.fillText(actor.name, 56, 500);
  context.font = "24px Arial";
  context.fillStyle = "rgba(255,255,255,.82)";
  context.fillText(actor.handle, 56, 538);
  context.font = "700 31px Arial";
  context.fillStyle = "#ffffff";
  wrapCanvasText(context, els.composeText.value.trim(), 56, 588, 1088, 38, 2);
  state.composeVisual = canvas.toDataURL("image/jpeg", 0.86);
  updateComposePreview(state.composeVisual);
}

function importComposeImage(file) {
  if (!file) return;
  const reader = new FileReader();
  reader.addEventListener("load", () => {
    state.composeVisual = String(reader.result || "");
    els.composeMediaSelect.value = "";
    updateComposePreview(state.composeVisual);
  });
  reader.readAsDataURL(file);
}

async function publishComposePost() {
  const actor = selectedComposeActor();
  if (!actor) return;
  if (!els.composeText?.value.trim()) generateComposeText();
  const content = els.composeText?.value.trim();
  if (!content) {
    if (els.composeLiveHint) els.composeLiveHint.textContent = "Ajoutez un message avant de publier.";
    els.composeText?.focus();
    return;
  }
  const publishButton = els.publishComposePost;
  const originalLabel = publishButton?.textContent || "Publier maintenant";
  if (publishButton) {
    publishButton.disabled = true;
    publishButton.textContent = "Publication…";
  }
  try {
    const liveDate = parisNow();
    const suspect = composeSuspect(actor);
    const selectedMedia = composeSelectedMedia();
    const media = state.composeVisual
      ? { kind: "photo", title: "Visuel créé par l'enseignant", caption: "", dataUrl: state.composeVisual, trace: "fr" }
      : selectedMedia ? structuredClone(selectedMedia) : null;
    let post = {
      id: `${state.scenario.id}-teacher-${Date.now()}`,
      actor,
      content,
      language: actor.language || "fr",
      suspect,
      reason: "Publication créée en direct par l'enseignant.",
      likes: 4 + Math.floor(Math.random() * 15),
      reposts: Math.floor(Math.random() * 5),
      replies: Math.floor(Math.random() * 4),
      media,
      liveDate,
      time: formatTime(liveDate),
      relativeTime: "à l'instant",
      teacherCreated: true,
      comments: []
    };
    post = normalizePostEngagement(post, liveDate);
    state.posts = [post, ...state.posts];
    persistTeacherPosts();
    renderScenarioInfo();
    renderFeed();
    els.composeDialog.close();
    publishLivePost(post).catch((error) => {
      console.warn("Publication locale réussie, diffusion en direct indisponible.", error);
      setLiveStatus("error", "Publication locale uniquement");
    });
  } catch (error) {
    console.error("Impossible de publier", error);
    if (els.composeLiveHint) els.composeLiveHint.textContent = "La publication a échoué. Réessayez sans image ou actualisez la page.";
  } finally {
    if (publishButton) {
      publishButton.disabled = false;
      publishButton.textContent = originalLabel;
    }
  }
}

function deleteTeacherPost(postId) {
  deleteLivePost(postId);
  state.posts = state.posts.filter((post) => post.id !== postId || !post.teacherCreated);
  persistTeacherPosts();
  renderScenarioInfo();
  renderFeed();
}

function bindEvents() {
  if (els.scenarioSelect) els.scenarioSelect.addEventListener("change", (event) => { loadScenario(event.target.value); announceLiveScenario(); });
  if (els.searchInput) els.searchInput.addEventListener("input", (event) => {
    state.query = event.target.value;
    if (els.clearSearch) els.clearSearch.hidden = !state.query;
    renderFeed();
  });
  if (els.clearSearch) els.clearSearch.addEventListener("click", () => {
    state.query = "";
    els.searchInput.value = "";
    els.clearSearch.hidden = true;
    renderFeed();
    els.searchInput.focus();
  });
  document.querySelectorAll(".segment").forEach((button) => {
    button.addEventListener("click", () => {
      document.querySelectorAll(".segment").forEach((item) => item.classList.remove("is-active"));
      button.classList.add("is-active");
      state.filter = button.dataset.filter;
      renderFeed();
    });
  });
  if (els.refreshFeedBtn) els.refreshFeedBtn.addEventListener("click", refreshFeedManually);
  if (els.composePostBtn) els.composePostBtn.addEventListener("click", openPostComposer);
  if (els.generateComposeText) els.generateComposeText.addEventListener("click", generateComposeText);
  if (els.generateComposeVisual) els.generateComposeVisual.addEventListener("click", generateComposeVisual);
  if (els.composeMediaSelect) els.composeMediaSelect.addEventListener("change", previewSelectedComposeMedia);
  if (els.composeUpload) els.composeUpload.addEventListener("change", (event) => importComposeImage(event.target.files[0]));
  if (els.publishComposePost) els.publishComposePost.addEventListener("click", publishComposePost);
  if (els.liveSessionBtn) els.liveSessionBtn.addEventListener("click", openLiveDialog);
  if (els.startLocalSession) els.startLocalSession.addEventListener("click", () => startLocalSession(1));
  if (els.startPhaseTwo) els.startPhaseTwo.addEventListener("click", () => startLocalSession(2));
  if (els.pauseSimulation) els.pauseSimulation.addEventListener("click", pauseSimulation);
  if (els.resumeSimulation) els.resumeSimulation.addEventListener("click", resumeSimulation);
  if (els.rewindSimulation) els.rewindSimulation.addEventListener("click", () => adjustSimulation(-5));
  if (els.advanceSimulation) els.advanceSimulation.addEventListener("click", () => adjustSimulation(5));
  if (els.simulationSpeed) els.simulationSpeed.addEventListener("change", (event) => changeSimulationSpeed(event.target.value));
  if (els.stopLiveSession) els.stopLiveSession.addEventListener("click", stopLiveSession);
  if (els.copyStudentLiveLink) els.copyStudentLiveLink.addEventListener("click", copyStudentLiveLink);
  if (els.feed) els.feed.addEventListener("click", (event) => {
    const button = event.target.closest("button[data-action]");
    if (!button) return;
    const post = event.target.closest(".post");
    if (!post) return;
    if (button.dataset.action === "profile") openProfile(button.dataset.handle);
    if (button.dataset.action === "flag") toggleFlag(post.dataset.postId);
    if (button.dataset.action === "annotate") openAnnotation(post.dataset.postId);
    if (button.dataset.action === "delete-teacher") deleteTeacherPost(post.dataset.postId);
    if (button.dataset.action === "translate-post") {
      const translation = post.querySelector(".post-translation");
      if (translation) {
        translation.hidden = !translation.hidden;
        button.setAttribute("aria-expanded", String(!translation.hidden));
        button.textContent = translation.hidden ? "Traduire le post" : "Masquer la traduction";
      }
    }
  });
  if (els.clearFlags) els.clearFlags.addEventListener("click", () => {
    state.flags.clear();
    renderFeed();
    renderFlags();
  });
  if (els.saveAnnotation) els.saveAnnotation.addEventListener("click", saveAnnotation);
  if (els.importBtn) els.importBtn.addEventListener("click", () => els.fileInput.click());
  if (els.fileInput) els.fileInput.addEventListener("change", async (event) => {
    const file = event.target.files[0];
    if (!file) return;
    try {
      await importScenario(file);
    } catch (error) {
      alert(`Import impossible : ${error.message}`);
    } finally {
      event.target.value = "";
    }
  });
  if (els.exportBtn) els.exportBtn.addEventListener("click", exportScenario);
  if (els.teacherToggle) els.teacherToggle.addEventListener("click", () => {
    if (els.scenarioEditor) els.scenarioEditor.value = JSON.stringify(state.scenario, null, 2);
    renderAnswerKey();
    els.teacherDialog.showModal();
  });
  if (els.applyScenario) els.applyScenario.addEventListener("click", applyScenarioJson);
  if (els.copyTemplate) els.copyTemplate.addEventListener("click", () => {
    els.scenarioEditor.value = JSON.stringify(emptyTemplate(), null, 2);
  });
}

renderScenarioOptions();
bindEvents();
// VEILLE-ILI BOOTSTRAP START
const requestedScenario = new URLSearchParams(window.location.search).get("scenario");
const initialScenarioId = isTeacherPage() && state.scenarios.some((item) => item.id === requestedScenario)
  ? requestedScenario
  : isTeacherPage()
    ? builtInScenarios[0].id
    : STUDENT_SCENARIO_ID;
loadScenario(initialScenarioId);
initializeLiveSync();
initializeStudentSessionCode();
void loadLiveNews(false);
// VEILLE-ILI BOOTSTRAP END
